API Gateway.diagram:
@startuml
!include https://raw.githubusercontent.com/plantuml-stdlib/C4-PlantUML/master/C4_Component.puml
LAYOUT_WITH_LEGEND()

Container_Boundary(api_gateway, "API Gateway") {
    Component(Ingress_Router, "Ingress Router", "Istio / AWS App Mesh Ingress", "Manages ingress routing, edge geo-routing, and incoming HTTPS requests.")
    Component(Rate_Limiter, "Rate Limiter", "Istio Service Mesh / AWS WAF Integration", "Enforces rate limiting and filters web traffic to protect downstream services.")
    Component(Authentication_Token_Verifier, "Authentication & Token Verifier", "AWS KMS / Istio Security", "Verifies and signs cryptographic JWS tokens for internal identity propagation.")
}

Rel(Ingress_Router, Rate_Limiter, "Forwards web traffic for inspection and rate limiting", "HTTPS")
Rel(Rate_Limiter, Authentication_Token_Verifier, "Delegates token verification for sanitized requests", "Internal AWS API")

@enduml

Catalog Container.diagram:
@startuml
!include https://raw.githubusercontent.com/plantuml-stdlib/C4-PlantUML/master/C4_Component.puml
LAYOUT_WITH_LEGEND()

title Component diagram for the Catalog Container container

Container_Boundary("Catalog Container", "Catalog Container") {
    Component(CatalogController, "Catalog Controller", "Amazon EKS / Microservices", "Handles incoming catalog and product metadata HTTP/HTTPS requests from the API Gateway.")
    Component(SearchQueryProcessor, "Search Query Processor", "AWS OpenSearch Integration", "Queries AWS OpenSearch for high-performance product metadata and pre-calculated regional pricing.")
    Component(RecommendationDataConsumer, "Recommendation Data Consumer", "Microservice Internal API", "Consumes and supplies catalog data for the Recommendation Engine Container via mTLS.")
}

Rel(CatalogController, SearchQueryProcessor, "Fetches product metadata and pricing")
Rel(RecommendationDataConsumer, CatalogController, "Retrieves catalog data via mTLS")

@enduml

Recommendation Engine Container.diagram:
@startuml
!include https://raw.githubusercontent.com/plantuml-stdlib/C4-PlantUML/master/C4_Component.puml
LAYOUT_WITH_LEGEND()

Container_Boundary(recommendation_engine_container, "Recommendation Engine Container") {
    Component(Recommendation Engine Core, "Recommendation Engine Core", "Amazon EKS Microservice", "Core microservice that delivers personalized, privacy-compliant book recommendations.")
    Component(Redis Sidecar, "Redis Sidecar", "Redis", "Caches pre-computed recommendations and user affinity profiles for sub-200ms response times.")
    Component(Istio Service Mesh, "Istio Service Mesh", "Istio", "Manages mTLS, traffic routing, and circuit breaking for the container.")
}

Rel(Istio Service Mesh, Recommendation Engine Core, "Routes internal inference requests", "mTLS")
Rel(Recommendation Engine Core, Redis Sidecar, "Retrieves cached recommendations", "TCP / AES-256")

@enduml
